insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$cordislandia$q$, $q$https://cordislandia.mg.leg.br/images/legislativo/leis/LEIS-2012/LEI_928.pdf (Lei 928/2012) ; https://cordislandia.mg.leg.br/index.php/leis (lista de leis da Câmara)$q$, $q$Ato oficial de Cordislândia: domínio público (Lei 9.610/1998, art. 8º, IV). Geometria da zona: setores censitários urbanos do IBGE 2022 (dados públicos, citar a fonte) recortados com as vias da BR-267/MGC-267 derivadas do OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 1, $q$Lei 928/2012: veículos com carregamento acima de 12 t impedidos nas ruas e avenidas da cidade (art. 1º), com a Av. Cônego Francisco como única via de transposição (art. 3º); o art. 2º limita a 10 t a ponte sobre o Rio Sapucaí sem identificá-la (regra desativada). A publicação oficial e a vigência atual não foram confirmadas (PDF sem assinatura do Prefeito; nenhuma lei posterior a altera ou revoga na lista da Câmara 2009-2026): confiança média. O perímetro urbano não é delimitado na lei: zona aproximada pelos setores urbanos do IBGE 2022.$q$);
